function point(e,plane){const rect=e.currentTarget.getBoundingClientRect(),a=Math.max(0,Math.min(e.currentTarget.width-1,Math.floor((e.clientX-rect.left)*e.currentTarget.width/rect.width))),b=Math.max(0,Math.min(e.currentTarget.height-1,Math.floor((e.clientY-rect.top)*e.currentTarget.height/rect.height)));return displayVoxelFromPlane(volume,plane,a,b,cross[plane==='axial'?2:plane==='coronal'?1:0]);}
