 const xyz=point(e,plane);
 if($('interaction-nav').checked){setCross(xyz);action('3D cursor moved. Drag adjusts WL/WW; Shift + drag zooms. Select Segment to mark blood.');gesture={kind:'window',pointer:e.pointerId,x:e.clientX,y:e.clientY,level:Number($('level').value),width:Number($('width').value),zoom,moved:false};c.setPointerCapture(e.pointerId);return;}
 discardCandidate();
 const tool=$('tool').value,label=Number($('label').value);
