function scan(files,isDirectory=false){inputGate.begin();if(!files.length)return;clearVolume();worker?.terminate();worker=new Worker('./io-worker.js?v=0.5.3');const current=worker,input=describeInput(files,isDirectory);status('Сканирование · '+input);$('series').hidden=$('load').hidden=true;worker.onerror=e=>{if(worker===current)status('Worker failure ('+input+'): '+e.message);};worker.onmessage=({data})=>{if(worker!==current)return;if(data.type==='error'){status('Measurement blocked [v0.5.3; '+input+']: '+data.message);return;}if(data.type==='groups'){const select=$('series');select.replaceChildren(...data.groups.map(g=>{const o=document.createElement('option');o.value=g.key;o.textContent=g.name+' · '+g.modality+' · '+g.frames+' slices · '+g.dims.join('×');return o;}));if(data.groups.length===1){select.hidden=$('load').hidden=true;status('One series found · decoding full CT stack…');worker.postMessage({type:'build',key:data.groups[0].key});}else{select.hidden=$('load').hidden=false;status('Choose a series ('+data.groups.length+' found; '+data.skipped+' skipped).');}}if(data.type==='volume')setVolume(data.volume);if(data.type==='progress')status(data.text+' '+Math.round(data.fraction*100)+'%');};worker.postMessage({type:'scan',slot:'ct',files:Array.from(files)});}
